from can_reverse_engineer.parsers.trc_probe import looks_like_trc, probe_trc

PCAN_V11 = """\
;$FILEVERSION=1.1
;$STARTTIME=46301.5921845255
;
;   Start time: 10/6/2026 14:12:44.743.0
;   Generated by PCAN-View v6.0.0.1040
;
;   Message Number
;   |         Time Offset (ms)
;   |         |        Type
;   |         |        |        ID (hex)
;   |         |        |        |     Data Length
;   |         |        |        |     |   Data Bytes (hex) ...
;   |         |        |        |     |   |
;---+--   ----+----  --+--  ----+---  +  -+ -- -- -- -- -- -- --
     1)     16045.9  Rx         07E2  8  03 22 F1 90 00 00 00 00 
     2)     16119.0  Rx         07DF  8  02 09 02 00 00 00 00 00 
     3)     16128.3  Rx         07DA  3  03 7F 09 
"""


def test_header_fields_and_legend_are_read_from_the_file():
    result = probe_trc(PCAN_V11)

    assert result["header_fields"] == {
        "FILEVERSION": "1.1",
        "STARTTIME": "46301.5921845255",
        "Start time": "10/6/2026 14:12:44.743.0",
        "Generated by": "PCAN-View v6.0.0.1040",
    }
    assert result["column_legend"] == [
        "Message Number", "Time Offset (ms)", "Type", "ID (hex)", "Data Length", "Data Bytes (hex) ...",
    ]
    assert result["header_line_count"] == 14
    assert result["data_line_count"] == 3


def test_sample_is_profiled_without_assuming_columns():
    result = probe_trc(PCAN_V11, sample_size=2)

    assert result["sample_size"] == 2
    assert result["sample_lines"][0].startswith("1)")
    assert result["token_count_distribution"] == {13: 2}
    first, second, third, fourth = result["column_profiles"][:4]
    assert first["kinds"] == {"index": 2}
    assert second["kinds"] == {"float": 2}
    assert third["examples"] == ["Rx"]
    assert fourth["examples"] == ["07E2", "07DF"]


def test_uneven_token_counts_are_reported():
    result = probe_trc(PCAN_V11)

    assert result["token_count_distribution"] == {13: 2, 8: 1}


def test_trc_signature_detection():
    assert looks_like_trc("\ufeff;$FILEVERSION=2.0\n")
    assert not looks_like_trc("timestamp,id,data\n")
    assert not looks_like_trc("")
